const DAY_MS = 86400000;
// A fixed, arbitrary epoch before this app existed — just needs to be stable across
// deploys so the same calendar day always maps to the same index.
const EPOCH_MS = new Date(2024, 0, 1).getTime();

/** Sequential day index (not hashed) — the spec wants cases to "rotate by day index...
 *  resets after 30 days," i.e. cycle through the bank in order, unlike Wordle/Crossword's
 *  hash-based word/puzzle-of-the-day. Takes the same "YYYY-MM-DD" dateKey used for the
 *  DailyCompletion row (see lib/wordle-words.ts's todayDateKey) rather than a Date, so the
 *  case shown for "today" and the case recorded as completed for "today" can never drift
 *  apart from computing "today" two different ways. */
export function dayIndexForDateKey(dateKey: string): number {
  const ms = new Date(dateKey + "T00:00:00Z").getTime();
  return Math.floor((ms - EPOCH_MS) / DAY_MS);
}

// Specialty rotation order — a full cycle every 6 days, same "don't spend five consecutive
// days on one specialty" reasoning the original 30-case bank's interleaved ordering had,
// but done arithmetically here instead of by hand-weaving all ~365 case literals into
// round-robin source order. Each specialty then cycles through its own bucket
// independently, so growing one specialty's bucket never reshuffles another's rotation.
const SPECIALTY_ROTATION = ["Orthopedic", "Neurological", "Sports", "Geriatric", "Pediatric", "General Wellness"];

const CASES_BY_SPECIALTY: Record<string, DailyCase[]> = (() => {
  const buckets: Record<string, DailyCase[]> = {};
  for (const specialty of SPECIALTY_ROTATION) buckets[specialty] = [];
  for (const c of CASES) buckets[c.specialty]?.push(c);
  return buckets;
})();

export function caseForDayIndex(dayIndex: number): DailyCase {
  const specialtyIdx = ((dayIndex % SPECIALTY_ROTATION.length) + SPECIALTY_ROTATION.length) % SPECIALTY_ROTATION.length;
  const specialty = SPECIALTY_ROTATION[specialtyIdx];
  const bucket = CASES_BY_SPECIALTY[specialty];
  const offset = Math.floor(dayIndex / SPECIALTY_ROTATION.length);
  const bucketIdx = ((offset % bucket.length) + bucket.length) % bucket.length;
  return bucket[bucketIdx];
}
